        // Let's assume beforeId is the one that will be AFTER the card, and afterId is the one that will be BEFORE.
        // Wait, the requirement says: "between afterId and beforeId".
        // Let's re-read: "accepting { columnId, beforeId, afterId }; the server computes the card's new position (between afterId and beforeId)".
        // So afterId < card < beforeId.
        const afterRes = await tx.query('SELECT position FROM cards WHERE id = $1', [afterId]);
        const beforeRes = await tx.query('SELECT position FROM cards WHERE id = $1', [beforeId]);

        if (afterRes.rows.length > 0 && beforeRes.rows.length > 0) {
          newPosition = (afterRes.rows[0].position + beforeRes.rows[0].position) / 2;
        } else if (afterRes.rows.length > 0) {
          newPosition = afterRes.rows[0].position + 1000.0;
        } else if (beforeRes.rows.length > 0) {
          newPosition = beforeRes.rows[0].position / 2;
        } else {
          newPosition = 1000.0;
        }
      }

      // Check for collisions or very small intervals
      // If the interval is too small, renormalize.
      // For simplicity, let's check if there are other cards with the same position or very close.
      // But a simpler way: if newPosition is very close to existing positions, renormalize.
      // Actually, let's just check if the position is extremely small/large.

      // For this implementation, let's just update and if we wanted to be robust, we'd check collisions.
      // A collision is when we find a card with the same position.
      const collisionRes = await tx.query('SELECT id FROM cards WHERE column_id = $1 AND position = $2', [columnId, newPosition]);
      if (collisionRes.rows.length > 0) {
