{"content": "const API_BASE = 'http://localhost:3001/api';
const SSE_URL = 'http://localhost:3001/api/stream';

let boardState = []; // Array of columns, each with cards

const app = document.getElementById('app');
const boardEl = document.getElementById('board');

async function fetchBoard() {
  const res = await fetch(`${API_BASE}/board`);
  boardState = await res.json();
  renderBoard();
}

function renderBoard() {
  boardEl.innerHTML = '';
  boardState.forEach(column => {
    const colEl = document.createElement('div');
    colEl.className = 'column';
    colEl.dataset.id = column.id;
    colEl.innerHTML = `
      <h2>${column.title}</h2>
      <div class="card-list" data-column-id="${column.id}"></div>
      <div class="add-card-form">
        <input type="text" placeholder="New card..." class="new-card-input">
        <button class="add-card-btn">Add</button>
      </div>
    `;

    const cardListEl = colEl.querySelector('.card-list');
    column.cards.forEach(card => {
      const cardEl = createCardElement(card);
      cardListEl.appendChild(cardEl);
    });

    const input = colEl.querySelector('.new-card-input');
    const btn = colEl.querySelector('.add-card-btn');

    btn.addEventListener('click', () => createCard(column.id, input.value));
    input.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') createCard(column.id, input.value);
    });

    // Drag and drop listeners for the column/card-list
    cardListEl.addEventListener('dragover', handleDragOver);
    cardListEl.addEventListener('drop', handleDrop);

    boardEl.appendChild(colEl);
  });
}

function createCardElement(card) {
  const cardEl = document.createElement('div');
  cardEl.className = 'card';
  cardEl.draggable = true;
  cardEl.id = `card-${card.id}`;
  cardEl.textContent = card.text;
  cardEl.dataset.id = card.id;

  cardEl.addEventListener('dragstart', handleDragStart);
  cardEl.addEventListener('dragend', handleDragEnd);

  return cardEl;
}

// --- State Management ---

async function createCard(columnId, text) {
  if (!text.trim()) return;

  const res = await fetch(`${API_BASE}/cards`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ columnId, text })
  });

  if (res.ok) {
    // We don't necessarily need to update local state here 
    // because SSE should broadcast it. 
    // But for responsiveness, we could.
  } else {
    alert('Failed to create card');
  }
}

let draggedCardId = null;

function handleDragStart(e) {
  draggedCardId = e.target.dataset.id;
  e.target.classList.add('dragging');
  e.dataTransfer.setData('text/plain', draggedCardId);
}

function handleDragEnd(e) {
  e.target.classList.remove('dragging');
  draggedCardId = null;
}

function handleDragOver(e) {
  e.preventDefault();
  const cardList = e.currentTarget;
  const afterElement = getDragAfterElement(cardList, e.clientY);
  const draggingEl = document.querySelector('.dragging');
  if (afterElement == null) {
    cardList.appendChild(draggingEl);
  } else {
    cardList.insertBefore(draggingEl, afterElement);
  }
}

function getDragAfterElement(container, y) {
  const draggableElements = [...container.querySelectorAll('.card:not(.dragging)')];

  return draggableElements.reduce((closest, child) => {
    const box = child.getBoundingClientRect();
    const offset = y - box.top - box.height / 2;
    if (offset < 0 && offset > closest.offset) {
      return { offset: offset, element: child };
    } else {
      return closest;
    }
  }, { offset: Number.NEGATIVE_INFINITY }).element;
}

async function handleDrop(e) {
  e.preventDefault();
  const cardListEl = e.currentTarget;
  const targetColumnId = cardListEl.dataset.columnId;

  // Find the card that was just moved
  const cardEl = document.getElementById(`card-${draggedCardId}`);
  if (!cardEl) return;

  // Determine beforeId and afterId for the move
  const siblings = [...cardListEl.querySelectorAll('.card:not(.dragging)')];
  const index = siblings.indexOf(cardEl); // This isn't quite right because cardEl is NOT in siblings if it's dragging... 
  // Wait, the DOM is already updated in handleDragOver (optimistically).
  // So cardEl IS in the DOM.

  // Let's find what's before and after it in the DOM.
  const allCardsInColumn = [...cardListEl.querySelectorAll('.card')];
  const myIndex = allCardsInColumn.indexOf(cardEl);

  const beforeId = myIndex > 0 ? allCardsInColumn[myIndex - 1].dataset.id : null;
  const afterId = myIndex < allCardsInColumn.length - 1 ? allCardsInColumn[myIndex + 1].dataset.id : null;

  // Find original column
  // We need to know where it came from to satisfy the "move across columns" requirement.
  // Actually, the API needs the new columnId.

  // To find the original column, we might need to store it when drag starts.
  // But wait, the move API: PATCH /api/cards/:id/move accepts { columnId, beforeId, afterId }.
  // So we need the NEW columnId.

  const movePayload = {
    columnId: targetColumnId,
    beforeId,
    afterId
  };

  // Optimistic update: we've already moved it in DOM via handleDragOver.
  // Now we send the request.

  try {
    const res = await fetch(`${API_BASE}/cards/${draggedCardId}/move`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(movePayload)
    });

    if (!res.ok) {
      throw new Error('Move failed');
    }

    // On success, the server will broadcast the canonical state.
    // We'll let the SSE handler update the UI.
  } catch (err) {
    console.error(err);
    // If it fails, re-fetch the board to revert to authoritative state.
    fetchBoard();
  }
}

// --- SSE ---

function setupSSE() {
  const eventSource = new EventSource(SSE_URL);

  eventSource.onmessage = (event) => {
    const { type, data } = JSON.parse(event.data);

    if (type === 'card_created' || type === 'card_moved') {
      // Re-fetch board to ensure full synchronization and correct ordering
      // This is the simplest way to guarantee convergence.
      fetchBoard();
    }
  };

  eventSource.onerror = (err) => {
    console.error('SSE error:', err);
  };
}

// --- Initialization ---

async function init() {
  await fetchBoard();
  setupSSE();
}

init();
